# Run on the FLEET (ot-run), never on localhost.  Exit 0 iff MUT 0 PASSES, every mutant FAILS and the audit PASSES.
#   bash rtl/qwen_dv/s5/s6/lp/qfd_dv_s6_lp_bench.sh OUTDIR        (SIM=iverilog default | verilator; VERILATOR, VL_JOBS, VL_EXTRA,
#   MUTS="0 1 .." optional overrides)
set -u
cd "${LP_ROOT:-$(git -C "$(dirname "$0")" rev-parse --show-toplevel 2>/dev/null || (cd "$(dirname "$0")/../../../../.." && pwd))}"
OUT=${1:-lp_bench_out}; mkdir -p "$OUT"; SIM=${SIM:-iverilog}; rc=0
SRCS="rtl/qwen_dv/s5/s6/qfd_dv_s6_flat.sv rtl/qwen_dv/s5/s6/qfd_dv_s6_leaves.sv rtl/qwen_dv/s5/qfd_dv_s5_leaves.sv rtl/qwen_dv/s5/p3/qfd_dv_s5_suvm_su8p3.sv rtl/qwen_dv/s5/p3/qfd_dv_s5_vm8q.sv rtl/qwen_dv/s5/qfd_dv_s5_vm8x.sv rtl/qwen_dv/s5/qfd_dv_s5_vm8out.sv rtl/qwen_dv/s5/qfd_dv_s5_su8.sv rtl/qwen_dv/s5/qfd_dv_s5_su8_rst3.sv rtl/qwen_dv/s5/p2/qfd_dv_s5_stm_closed.sv rtl/qwen_dv/qfd_dv_stream_tile.sv rtl/qwen_dv/s5/qfd_dv_s5_ctl_repair4_leaf.sv rtl/qwen_dv/s5/qfd_dv_s5_ctl_repair4.sv rtl/qwen_dv/s5/qfd_dv_s5_ctl_repair4_helpers.sv rtl/qwen_dv/s5/qfd_dv_s5_btab_s4.sv rtl/qwen_dv/s5/qfd_dv_s5_btab_safe.sv rtl/qwen_dv/qfd_dv_redstn2_regional.sv rtl/qwen_dv/qfd_dv_head_safe1.sv rtl/hdc/ot_hdc_vstream_sfu_t.sv rtl/qwen_sys/dvm_20261014/ot_qfd_xslice.sv rtl/common/landed_parent/ot_pl_land.sv rtl/common/landed_parent/ot_pl_land_rst_copy.sv rtl/common/landed_parent/ot_pl_land_split.sv rtl/qwen_dv/s5/s6/lp/qfd_dv_s6_flat_lagref.sv rtl/qwen_dv/s5/s6/lp/qfd_dv_s6_lp.sv rtl/qwen_dv/s5/s6/lp/tb_qfd_dv_s6_lp.sv"
python3 tools/landed_parent/lp.py audit tools/landed_parent/specs/qfd_dv_s6.json > "$OUT/audit.log" 2>&1 && echo "AUDIT PASS" || { echo "AUDIT FAIL"; rc=1; }
python3 tools/landed_parent/lp.py audit tools/landed_parent/specs/qfd_dv_s6.json --rtl "$OUT/unland.sv" --make-unland > "$OUT/audit_unland.log" 2>&1 \
  && { echo "AUDIT-UNLAND PASSED (should FAIL)"; rc=1; } || echo "AUDIT-UNLAND FAIL (expected)"
for m in ${MUTS:-0 1 2 4}; do
  if [ "$SIM" = verilator ]; then
    ${VERILATOR:-verilator} --binary -j ${VL_JOBS:-8} -I. -Wno-fatal -Wno-lint -Wno-style -Wno-TIMESCALEMOD -Wno-WIDTHCONCAT -O1 ${VL_EXTRA:-} --top-module tb_qfd_dv_s6_lp -GMUT=$m -DOT_S5_HARD $SRCS -Mdir "$OUT/obj$m" > "$OUT/build_$m.log" 2>&1 \
